import { useEffect, useMemo, useState } from "react";
import {
  MessageCircle,
  Phone,
  RefreshCw,
  Search,
  Filter,
  Calendar,
} from "lucide-react";
import { toast } from "sonner";
import {
  getChatbotLeads,
  updateChatbotLeadStatus,
  type ChatbotLead,
  type ChatbotLeadStatus,
} from "@/admin/lib/adminChatbot";
import AdminLayout from "../components/AdminLayout"; // Added sidebar wrapper

const STATUS_OPTIONS: ChatbotLeadStatus[] = [
  "new",
  "contacted",
  "converted",
  "closed",
];

const FLOW_OPTIONS = [
  { value: "", label: "All Flows" },
  { value: "shop_sarees", label: "Shop Sarees" },
  { value: "video_shopping", label: "Video Shopping" },
  { value: "custom_bulk", label: "Custom / Bulk" },
  { value: "support", label: "Support" },
];

const statusClass: Record<ChatbotLeadStatus, string> = {
  new: "bg-blue-50 text-blue-700 border-blue-200",
  contacted: "bg-yellow-50 text-yellow-700 border-yellow-200",
  converted: "bg-green-50 text-green-700 border-green-200",
  closed: "bg-gray-50 text-gray-700 border-gray-200",
};

function formatFlow(flow: string) {
  return flow
    .replaceAll("_", " ")
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

function formatDate(value: string) {
  return new Date(value).toLocaleString("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function whatsappLink(phone: string, name?: string, flow?: string) {
  const cleaned = phone.replace(/\D/g, "");
  const finalPhone = cleaned.startsWith("91") ? cleaned : `91${cleaned}`;

  const readableFlow = flow ? formatFlow(flow) : "your enquiry";

  const message = encodeURIComponent(
    `Hi ${name || ""}, this is NEYGE Couture 🌸

We received your request for ${readableFlow}.

Our team will assist you in choosing the perfect saree based on your occasion, fabric, color and budget.

Please let us know a convenient time to connect.

Thank you,
NEYGE Couture`
  );

  return `https://wa.me/${finalPhone}?text=${message}`;
}

function StatCard({ title, value }: { title: string; value: number }) {
  return (
    <div className="bg-white border border-[#EAD9C5] rounded-2xl p-5 shadow-sm">
      <p className="text-sm text-[#4a3828]/60">{title}</p>
      <p className="text-3xl font-bold text-[#800020] mt-1">{value}</p>
    </div>
  );
}

export default function AdminChatbotLeads() {
  const [leads, setLeads] = useState<ChatbotLead[]>([]);
  const [loading, setLoading] = useState(false);
  const [flow, setFlow] = useState("");
  const [status, setStatus] = useState("");
  const [search, setSearch] = useState("");

  const fetchLeads = async () => {
    setLoading(true);
    try {
      const data = await getChatbotLeads({
        flow: flow || undefined,
        status: status || undefined,
      });
      setLeads(data);
    } catch (error) {
      console.error(error);
      toast.error("Failed to fetch chatbot leads");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLeads();
  }, [flow, status]);

  const filteredLeads = useMemo(() => {
    const q = search.toLowerCase().trim();
    if (!q) return leads;
    return leads.filter((lead) =>
      [
        lead.name,
        lead.phone,
        lead.email,
        lead.city,
        lead.occasion,
        lead.budget,
        lead.saree_type,
        lead.requirement_type,
        lead.message,
      ]
        .filter(Boolean)
        .join(" ")
        .toLowerCase()
        .includes(q)
    );
  }, [leads, search]);

  const handleStatusChange = async (
    leadId: string,
    nextStatus: ChatbotLeadStatus
  ) => {
    try {
      const updated = await updateChatbotLeadStatus(leadId, nextStatus);
      setLeads((prev) =>
        prev.map((lead) => (lead.id === leadId ? updated : lead))
      );
      toast.success("Lead status updated");
    } catch (error) {
      console.error(error);
      toast.error("Failed to update status");
    }
  };

  const stats = useMemo(() => {
    return {
      total: leads.length,
      new: leads.filter((lead) => lead.status === "new").length,
      contacted: leads.filter((lead) => lead.status === "contacted").length,
      converted: leads.filter((lead) => lead.status === "converted").length,
    };
  }, [leads]);

  return (
    <AdminLayout title="Chatbot Leads">
      <div className="space-y-6">
        {/* Header with title and refresh button */}
        <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
          <div>
            <div className="flex items-center gap-2 text-[#800020]">
              <MessageCircle size={24} />
              <h1 className="text-2xl font-bold">Chatbot Leads</h1>
            </div>
            <p className="text-sm text-[#4a3828]/70 mt-1">
              Manage shop, video shopping, bulk enquiry and support leads.
            </p>
          </div>

          <button
            onClick={fetchLeads}
            className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-[#800020] text-white font-semibold shadow border border-[#D4AF37]"
          >
            <RefreshCw size={16} className={loading ? "animate-spin" : ""} />
            Refresh
          </button>
        </div>

        {/* Stats Cards */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <StatCard title="Total Leads" value={stats.total} />
          <StatCard title="New" value={stats.new} />
          <StatCard title="Contacted" value={stats.contacted} />
          <StatCard title="Converted" value={stats.converted} />
        </div>

        {/* Filters */}
        <div className="bg-white border border-[#EAD9C5] rounded-2xl p-4 shadow-sm">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-3">
            <div className="relative md:col-span-2">
              <Search
                size={17}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-[#4a3828]/50"
              />
              <input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search name, phone, budget, message..."
                className="w-full pl-10 pr-3 py-2.5 border border-[#EAD9C5] rounded-xl outline-none focus:ring-2 focus:ring-[#C4980A]/30"
              />
            </div>

            <div className="relative">
              <Filter
                size={17}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-[#4a3828]/50"
              />
              <select
                value={flow}
                onChange={(e) => setFlow(e.target.value)}
                className="w-full pl-10 pr-3 py-2.5 border border-[#EAD9C5] rounded-xl outline-none bg-white"
              >
                {FLOW_OPTIONS.map((item) => (
                  <option key={item.value} value={item.value}>
                    {item.label}
                  </option>
                ))}
              </select>
            </div>

            <select
              value={status}
              onChange={(e) => setStatus(e.target.value)}
              className="w-full px-3 py-2.5 border border-[#EAD9C5] rounded-xl outline-none bg-white"
            >
              <option value="">All Status</option>
              {STATUS_OPTIONS.map((item) => (
                <option key={item} value={item}>
                  {item.toUpperCase()}
                </option>
              ))}
            </select>
          </div>
        </div>

        {/* Leads Table */}
        <div className="bg-white border border-[#EAD9C5] rounded-2xl shadow-sm overflow-hidden">
          {loading ? (
            <div className="p-10 text-center text-[#4a3828]/70">
              Loading chatbot leads...
            </div>
          ) : filteredLeads.length === 0 ? (
            <div className="p-10 text-center text-[#4a3828]/70">
              No chatbot leads found.
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full min-w-[1100px] text-sm">
                <thead className="bg-[#F5E6D3] text-[#4a3828]">
                  <tr>
                    <th className="text-left p-4">Customer</th>
                    <th className="text-left p-4">Flow</th>
                    <th className="text-left p-4">Details</th>
                    <th className="text-left p-4">Message</th>
                    <th className="text-left p-4">Status</th>
                    <th className="text-left p-4">Created</th>
                    <th className="text-left p-4">Action</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredLeads.map((lead) => (
                    <tr
                      key={lead.id}
                      className="border-t border-[#EAD9C5] align-top hover:bg-[#FFF9F0]"
                    >
                      <td className="p-4">
                        <p className="font-bold text-[#800020]">{lead.name}</p>
                        <p className="text-[#4a3828]">{lead.phone}</p>
                        {lead.email && (
                          <p className="text-xs text-[#4a3828]/60">
                            {lead.email}
                          </p>
                        )}
                        {lead.city && (
                          <p className="text-xs text-[#4a3828]/60">
                            City: {lead.city}
                          </p>
                        )}
                      </td>

                      <td className="p-4">
                        <span className="inline-flex px-3 py-1 rounded-full bg-[#800020]/10 text-[#800020] font-semibold">
                          {formatFlow(lead.flow)}
                        </span>
                      </td>

                      <td className="p-4 space-y-1 text-[#4a3828]">
                        {lead.saree_type && <p>Saree: {lead.saree_type}</p>}
                        {lead.occasion && <p>Occasion: {lead.occasion}</p>}
                        {lead.budget && <p>Budget: {lead.budget}</p>}
                        {lead.requirement_type && (
                          <p>Type: {lead.requirement_type}</p>
                        )}
                        {lead.approx_quantity && (
                          <p>Qty: {lead.approx_quantity}</p>
                        )}
                        {lead.preferred_date && (
                          <p className="flex items-center gap-1">
                            <Calendar size={14} />
                            {lead.preferred_date} {lead.preferred_time || ""}
                          </p>
                        )}
                      </td>

                      <td className="p-4 max-w-[280px]">
                        <p className="text-[#4a3828]/80 line-clamp-4">
                          {lead.message || "-"}
                        </p>
                      </td>

                      <td className="p-4">
                        <select
                          value={lead.status}
                          onChange={(e) =>
                            handleStatusChange(
                              lead.id,
                              e.target.value as ChatbotLeadStatus
                            )
                          }
                          className={`border rounded-xl px-3 py-2 font-semibold ${statusClass[lead.status]
                            }`}
                        >
                          {STATUS_OPTIONS.map((item) => (
                            <option key={item} value={item}>
                              {item.toUpperCase()}
                            </option>
                          ))}
                        </select>
                      </td>

                      <td className="p-4 text-[#4a3828]/70">
                        {formatDate(lead.created_at)}
                      </td>

                      <td className="p-4">
                        <a
                          href={whatsappLink(lead.phone, lead.name, lead.flow)}
                          target="_blank"
                          rel="noreferrer"
                          className="inline-flex items-center gap-2 px-3 py-2 rounded-xl bg-green-600 text-white font-semibold hover:bg-green-700 transition"
                        >
                          <Phone size={15} />
                          WhatsApp
                        </a>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </AdminLayout>
  );
}

import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import AdminLayout from "../components/AdminLayout";
import adminApi from "../lib/adminApi";
import { Plus, Edit, Trash2, Layers } from "lucide-react";

const CSS = `
.admin-header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
}
.admin-header-title {
  font-family: 'Cinzel', serif;
  font-size: clamp(24px, 5vw, 28px);
  font-weight: 400;
  color: #800020;
  margin: 0;
}
.admin-add-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  background: linear-gradient(135deg, #D4AF37, #b8960f);
  color: #800020;
  border-radius: 100px;
  font-weight: 600;
  font-size: 13px;
  text-decoration: none;
}
.admin-stats {
  background: rgba(255,249,240,.97);
  border: 1px solid rgba(196,152,10,.22);
  border-radius: 24px;
  padding: 12px 20px;
  display: inline-block;
  margin-bottom: 24px;
}
.admin-card {
  background: rgba(255,249,240,.97);
  border: 1px solid rgba(196,152,10,.22);
  border-radius: 24px;
  padding: 20px;
}
.admin-collection-item {
  background: rgba(255,249,240,.9);
  border: 1px solid rgba(196,152,10,.2);
  border-radius: 20px;
  padding: 16px;
  margin-bottom: 16px;
}
.admin-collection-content {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
@media (min-width: 768px) {
  .admin-collection-content {
    flex-direction: row;
    align-items: flex-start;
  }
}
.admin-collection-img {
  width: 80px;
  height: 80px;
  border-radius: 16px;
  object-fit: cover;
  border: 1px solid rgba(196,152,10,.3);
}
.admin-collection-info {
  flex: 1;
}
.admin-collection-name {
  font-family: 'Cinzel', serif;
  font-size: 20px;
  font-weight: 500;
  color: #800020;
  margin-bottom: 6px;
}
.admin-collection-meta {
  font-size: 12px;
  color: #9a8070;
  margin-bottom: 8px;
}
.admin-collection-desc {
  font-size: 13px;
  color: #4a3828;
  font-weight: 300;
  margin-top: 6px;
}
.status-active {
  background: rgba(34,197,94,.12);
  color: #059669;
  border: 1px solid rgba(34,197,94,.3);
  display: inline-block;
  padding: 4px 12px;
  border-radius: 100px;
  font-size: 11px;
  font-weight: 600;
}
.status-inactive {
  background: rgba(156,163,175,.12);
  color: #6b7280;
  border: 1px solid rgba(156,163,175,.3);
  display: inline-block;
  padding: 4px 12px;
  border-radius: 100px;
  font-size: 11px;
  font-weight: 600;
}
.admin-collection-actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.admin-edit-btn, .admin-delete-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border-radius: 100px;
  font-size: 12px;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
}
.admin-edit-btn {
  border: 1.5px solid rgba(196,152,10,.4);
  color: #800020;
  background: transparent;
}
.admin-delete-btn {
  border: 1.5px solid rgba(220,38,38,.3);
  color: #dc2626;
  background: transparent;
}
@media (max-width: 640px) {
  .admin-collection-actions {
    justify-content: flex-end;
    width: 100%;
  }
  .admin-edit-btn, .admin-delete-btn {
    flex: 1;
    justify-content: center;
  }
}
`;

type Collection = {
  id: string; name?: string; slug?: string; description?: string;
  image?: string | null; thumbnail?: string | null; is_active?: boolean;
};

export default function AdminCollections() {
  // ✅ Scroll to top when this page loads
  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  const [collections, setCollections] = useState<Collection[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const fetchCollections = async () => {
    try {
      setLoading(true);
      const res = await adminApi.get("/collections");
      const items = Array.isArray(res.data) ? res.data : (res.data?.data?.items || res.data?.data || res.data?.collections || []);
      setCollections(items);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Delete this collection?")) return;
    try {
      await adminApi.delete(`/collections/${id}`);
      await fetchCollections();
    } catch {
      alert("Delete failed");
    }
  };

  useEffect(() => { fetchCollections(); }, []);

  if (loading) return <AdminLayout title="Collections"><div className="admin-loading">Loading...</div></AdminLayout>;
  if (error) return <AdminLayout title="Collections"><div className="admin-error">{error}</div></AdminLayout>;

  return (
    <>
      <style>{CSS}</style>
      <AdminLayout title="Collections">
        <div className="admin-header">
          <h1 className="admin-header-title">Collections</h1>
          <Link to="/admin/collections/new" className="admin-add-btn"><Plus size={16} /> Add Collection</Link>
        </div>
        <div className="admin-stats">Total collections: <strong>{collections.length}</strong></div>
        <div className="admin-card">
          {collections.length === 0 ? (
            <div style={{ textAlign: "center", padding: 40 }}>No collections found.</div>
          ) : (
            collections.map(coll => (
              <div key={coll.id} className="admin-collection-item">
                <div className="admin-collection-content">
                  <div>
                    {coll.image || coll.thumbnail ? (
                      <img src={coll.image || coll.thumbnail || ""} alt={coll.name} className="admin-collection-img" />
                    ) : (
                      <div className="admin-collection-img" style={{ background: "#f1e4d2", display: "flex", alignItems: "center", justifyContent: "center" }}>
                        <Layers size={32} color="#C4980A" />
                      </div>
                    )}
                  </div>
                  <div className="admin-collection-info">
                    <div className="admin-collection-name">{coll.name || "Untitled"}</div>
                    <div className="admin-collection-meta">Slug: {coll.slug || "-"}</div>
                    {coll.description && <div className="admin-collection-desc">{coll.description}</div>}
                    <div style={{ marginTop: 8 }}>
                      <span className={coll.is_active ? "status-active" : "status-inactive"}>
                        {coll.is_active ? "Active" : "Inactive"}
                      </span>
                    </div>
                  </div>
                  <div className="admin-collection-actions">
                    <Link to={`/admin/collections/${coll.id}/edit`} className="admin-edit-btn"><Edit size={14} /> Edit</Link>
                    <button onClick={() => handleDelete(coll.id)} className="admin-delete-btn"><Trash2 size={14} /> Delete</button>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </AdminLayout>
    </>
  );
}

import { useEffect, useMemo, useState } from "react";
import { Link } from "react-router-dom";
import AdminLayout from "../components/AdminLayout";
import adminApi from "../lib/adminApi";
import {
  Package,
  Layers,
  ShoppingBag,
  TrendingUp,
  Video,
  Sparkles,
} from "lucide-react";

// ─── Brand palette (matches all other pages) ─────────────────────────────────
const C = {
  maroon: '#800020',
  maroonDk: '#5a0016',
  gold: '#C4980A',
  goldV: '#D4AF37',
  cream: '#F5E6D3',
  creamLt: '#FFF9F0',
  creamMid: '#F8EEE2',
  warmGrey: '#4a3828',
  navy: '#1B2A6B',
};

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;500;600;700&family=Josefin+Sans:ital,wght@0,300;0,400;0,500;0,600;1,300;1,400&display=swap');

.admin-dashboard {
  font-family: 'Josefin Sans', sans-serif;
  word-break: break-word;
}

/* Stats Cards */
.admin-stat-card {
  background: rgba(255,249,240,.97);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(196,152,10,.22);
  border-radius: 24px;
  padding: 24px;
  transition: transform .3s, box-shadow .3s;
}
.admin-stat-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 40px rgba(128,0,32,.1);
  border-color: rgba(196,152,10,.4);
}
.admin-stat-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: rgba(196,152,10,.12);
  border: 1px solid rgba(196,152,10,.3);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
}
.admin-stat-label {
  font-family: 'Josefin Sans';
  font-size: 12px;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: #9a8070;
  font-weight: 500;
  margin-bottom: 8px;
}
.admin-stat-value {
  font-family: 'Cinzel', serif;
  font-size: 32px;
  font-weight: 500;
  color: #800020;
  line-height: 1;
  margin-bottom: 12px;
  letter-spacing: 0.02em;
}
.admin-stat-link {
  font-family: 'Josefin Sans';
  font-size: 12px;
  font-weight: 600;
  color: #C4980A;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: gap .25s;
  padding: 4px 0;
}
.admin-stat-link:hover { gap: 10px; color: #800020; }

/* Section Cards */
.admin-section-card {
  background: rgba(255,249,240,.97);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(196,152,10,.22);
  border-radius: 24px;
  padding: 24px;
  box-shadow: 0 8px 36px rgba(0,0,0,.06);
}
.admin-section-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 20px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(196,152,10,.18);
}
.admin-section-title {
  font-family: 'Cinzel', serif;
  font-size: 20px;
  font-weight: 500;
  color: #800020;
  letter-spacing: 0.02em;
}
.admin-section-link {
  font-family: 'Josefin Sans';
  font-size: 12px;
  font-weight: 600;
  color: #C4980A;
  text-decoration: none;
  transition: color .2s;
  padding: 4px 0;
}
.admin-section-link:hover { color: #800020; }

/* List Items */
.admin-list-item {
  background: rgba(255,249,240,.9);
  border: 1px solid rgba(196,152,10,.2);
  border-radius: 18px;
  padding: 16px;
  margin-bottom: 12px;
  transition: box-shadow .25s, border-color .25s;
}
.admin-list-item:hover {
  box-shadow: 0 6px 22px rgba(128,0,32,.09);
  border-color: rgba(196,152,10,.4);
}
.admin-list-title {
  font-family: 'Cinzel', serif;
  font-size: 16px;
  font-weight: 500;
  color: #800020;
  margin-bottom: 6px;
  letter-spacing: 0.02em;
}
.admin-list-meta {
  font-family: 'Josefin Sans';
  font-size: 12px;
  color: #9a8070;
  font-weight: 300;
  line-height: 1.6;
}

/* Loading & Error */
.admin-loading,
.admin-error {
  background: rgba(255,249,240,.97);
  border: 1px solid rgba(196,152,10,.22);
  border-radius: 24px;
  padding: 32px;
  text-align: center;
  font-family: 'Josefin Sans';
  font-size: 14px;
}
