  border-color: rgba(220,38,38,.3);
  background: rgba(254,226,226,.8);
}

.admin-empty {
  text-align: center;
  padding: 48px 24px;
}
.admin-empty-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: rgba(196,152,10,.12);
  border: 1px solid rgba(196,152,10,.3);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
}
.admin-empty-text {
  font-size: 14px;
  color: #9a8070;
  font-weight: 300;
}
`;

type Product = {
  id: string;
  name?: string;
  slug?: string;
  price?: number;
  discount_price?: number | null;
  thumbnail?: string | null;
  stock?: number;
  is_active?: boolean;
};

export default function AdminProducts() {
  // ✅ Scroll to top when this page loads
  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const fetchProducts = async () => {
    try {
      setLoading(true);
      setError("");

      const res = await adminApi.get("/products");
      console.log("PRODUCTS API RESPONSE:", res.data);

      let items: Product[] = [];

      if (Array.isArray(res.data)) {
        items = res.data;
      } else if (Array.isArray(res.data?.data)) {
        items = res.data.data;
      } else if (Array.isArray(res.data?.data?.items)) {
        items = res.data.data.items;
      } else if (Array.isArray(res.data?.products)) {
        items = res.data.products;
      } else if (Array.isArray(res.data?.items)) {
        items = res.data.items;
      }

      setProducts(items);
    } catch (err: any) {
      console.error("Failed to fetch products:", err);
      setError(err?.message || "Failed to fetch products");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    const ok = window.confirm("Are you sure you want to delete this product?");
    if (!ok) return;

    try {
      await adminApi.delete(`/products/${id}`);
      await fetchProducts();
    } catch (error) {
      console.error("Failed to delete product:", error);
      alert("Delete failed");
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  return (
    <>
      <style>{CSS}</style>
      <AdminLayout title="Products">
        <div className="admin-products">
          <div className="admin-header">
            <h1 className="admin-header-title">Products</h1>
            <Link to="/admin/products/new" className="admin-add-btn">
              <Plus size={16} /> Add Product
            </Link>
          </div>

          {loading && (
            <div className="admin-loading">Loading products...</div>
          )}

          {error && (
            <div className="admin-error">{error}</div>
          )}

          {!loading && !error && (
            <>
              <div className="admin-stats">
                <span className="admin-stats-text">
                  Total products: <span className="admin-stats-number">{products.length}</span>
                </span>
              </div>

              <div className="admin-card">
                {products.length === 0 ? (
                  <div className="admin-empty">
                    <div className="admin-empty-icon">
                      <Package size={28} color={C.gold} />
                    </div>
                    <p className="admin-empty-text">No products found.</p>
                  </div>
                ) : (
                  products.map((product) => (
                    <div key={product.id} className="admin-product-item">
                      <div className="admin-product-content">
                        <div>
                          {product.thumbnail ? (
                            <img
                              src={product.thumbnail}
                              alt={product.name || "Product"}
                              className="admin-product-img"
                            />
                          ) : (
                            <div
                              className="admin-product-img"
                              style={{
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                background: "#f1e4d2",
                              }}
                            >
                              <Package size={32} color={C.gold} />
                            </div>
                          )}
                        </div>

                        <div className="admin-product-info">
                          <div className="admin-product-name">
                            {product.name || "Untitled Product"}
                          </div>
                          <div className="admin-product-meta">
                            Slug: {product.slug || "-"}
                          </div>
                          <div className="admin-product-meta">
                            Stock: {product.stock ?? 0}
                          </div>
                          <div className="admin-product-price">
                            ₹{product.discount_price ?? product.price ?? 0}
                          </div>
                          <div style={{ marginTop: 8 }}>
                            <span className={product.is_active ? "status-active" : "status-inactive"}>
                              {product.is_active ? "Active" : "Inactive"}
                            </span>
                          </div>
                        </div>

                        <div className="admin-product-actions">
                          <Link
                            to={`/admin/products/${product.id}/edit`}
                            className="admin-edit-btn"
                          >
                            <Edit size={14} /> Edit
                          </Link>
                          <button
                            onClick={() => handleDelete(product.id)}
                            className="admin-delete-btn"
                          >
                            <Trash2 size={14} /> Delete
                          </button>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </>
          )}
        </div>
      </AdminLayout>
    </>
  );
}

import { useEffect, useMemo, useState } from "react";
import {
  CalendarDays,
  CheckCircle2,
  Clock3,
  Mail,
  Phone,
  XCircle,
  Video,
  SlidersHorizontal,
  ChevronDown,
} from "lucide-react";
import { toast } from "sonner";
import AdminLayout from "../components/AdminLayout";
import { useAdminVideoBookings } from "../../hooks/useAdminVideoBookings";

// ─── Brand palette (matches all other pages) ─────────────────────────────────
const C = {
  maroon: '#800020',
  maroonDk: '#5a0016',
  gold: '#C4980A',
  goldV: '#D4AF37',
  cream: '#F5E6D3',
  creamLt: '#FFF9F0',
  creamMid: '#F8EEE2',
  warmGrey: '#4a3828',
  navy: '#1B2A6B',
};

const STATUS_OPTIONS = ["all", "pending", "confirmed", "completed", "cancelled"] as const;
type BookingStatus = "pending" | "confirmed" | "completed" | "cancelled";

const STATUS_CONFIG: Record<
  BookingStatus,
  { label: string; dot: string; text: string; bg: string; border: string }
> = {
  pending: {
    label: "Pending",
    dot: "#F59E0B",
    text: "#92400E",
    bg: "#FFFBEB",
    border: "#FDE68A",
  },
  confirmed: {
    label: "Confirmed",
    dot: "#3B82F6",
    text: "#1E40AF",
    bg: "#EFF6FF",
    border: "#BFDBFE",
  },
  completed: {
    label: "Completed",
    dot: "#10B981",
    text: "#065F46",
    bg: "#ECFDF5",
    border: "#A7F3D0",
  },
  cancelled: {
    label: "Cancelled",
    dot: "#EF4444",
    text: "#991B1B",
    bg: "#FEF2F2",
    border: "#FECACA",
  },
};

const STAT_CARDS = [
  { key: "total", filterKey: "all", label: "Total", color: "#6366F1", bg: "#EEF2FF", border: "#C7D2FE" },
  { key: "pending", filterKey: "pending", label: "Pending", color: "#D97706", bg: "#FFFBEB", border: "#FDE68A" },
  { key: "confirmed", filterKey: "confirmed", label: "Confirmed", color: "#2563EB", bg: "#EFF6FF", border: "#BFDBFE" },
  { key: "completed", filterKey: "completed", label: "Completed", color: "#059669", bg: "#ECFDF5", border: "#A7F3D0" },
  { key: "cancelled", filterKey: "cancelled", label: "Cancelled", color: "#DC2626", bg: "#FEF2F2", border: "#FECACA" },
] as const;

function formatDate(dateString?: string) {
  if (!dateString) return "—";
  const d = new Date(dateString);
  if (isNaN(d.getTime())) return "—";
  return d.toLocaleString("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function StatusBadge({ status }: { status: BookingStatus }) {
  const cfg = STATUS_CONFIG[status];
  return (
    <span
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 6,
        padding: "4px 12px",
        borderRadius: 100,
        fontSize: 11,
        fontWeight: 600,
        fontFamily: "'Josefin Sans', sans-serif",
        letterSpacing: "0.04em",
        background: cfg.bg,
        color: cfg.text,
        border: `1px solid ${cfg.border}`,
        textTransform: "capitalize",
        whiteSpace: "nowrap",
      }}
    >
      <span style={{ width: 6, height: 6, borderRadius: "50%", background: cfg.dot, flexShrink: 0 }} />
      {cfg.label}
    </span>
  );
}

export default function AdminVideoBookingsPage() {
  // ✅ Scroll to top when this page loads
  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  const { bookings, loading, updatingId, updateStatus } = useAdminVideoBookings();
  const [filter, setFilter] = useState<(typeof STATUS_OPTIONS)[number]>("all");

  const filteredBookings = useMemo(() => {
    if (filter === "all") return bookings;
    return bookings.filter((b) => b.status === filter);
  }, [bookings, filter]);

  const stats = useMemo(() => ({
    total: bookings.length,
    pending: bookings.filter((b) => b.status === "pending").length,
    confirmed: bookings.filter((b) => b.status === "confirmed").length,
    completed: bookings.filter((b) => b.status === "completed").length,
    cancelled: bookings.filter((b) => b.status === "cancelled").length,
  }), [bookings]);

  const handleStatusChange = async (bookingId: string, status: BookingStatus) => {
    try {
      await updateStatus(bookingId, status);
      toast.success(`Booking marked as ${status}`);
    } catch (error: any) {
      toast.error(error?.response?.data?.message || "Failed to update booking status");
    }
  };

  return (
    <AdminLayout title="Video Bookings">
      <style>{`
        .vb-brand {
          font-family: 'Josefin Sans', sans-serif;
        }
        .vb-title {
          font-family: 'Cinzel', serif;
          font-weight: 400;
          letter-spacing: 0.04em;
          color: #800020;
        }
        @media (max-width: 640px) {
          .vb-stats-grid {
            grid-template-columns: repeat(2, 1fr) !important;
          }
          .vb-action-col {
            width: 100% !important;
          }
          .vb-booking-card {
            flex-direction: column !important;
          }
        }
      `}</style>
      <div className="vb-brand" style={{ minHeight: "100vh" }}>
        <div style={{ maxWidth: 1320, margin: "0 auto", padding: "0 20px 60px" }}>
          {/* Header */}
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              justifyContent: "space-between",
              alignItems: "center",
              gap: 16,
              marginBottom: 32,
              paddingTop: 8,
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
              <div
                style={{
                  width: 48,
                  height: 48,
                  borderRadius: 16,
                  background: `linear-gradient(135deg, ${C.maroon}, ${C.navy})`,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  boxShadow: "0 6px 18px rgba(128,0,32,0.25)",
                }}
              >
                <Video size={22} color="white" />
              </div>
              <div>
                <h1 className="vb-title" style={{ fontSize: "clamp(24px, 5vw, 28px)", margin: 0 }}>
                  Video Bookings
                </h1>
                <p style={{ fontSize: 13, color: C.warmGrey, margin: "4px 0 0", fontWeight: 300 }}>
                  Manage consultations and update statuses
                </p>
              </div>
            </div>

            {/* Filter dropdown */}
            <div style={{ position: "relative", minWidth: 140 }}>
              <SlidersHorizontal size={14} color={C.gold} style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", pointerEvents: "none" }} />
              <select
                value={filter}
                onChange={(e) => setFilter(e.target.value as any)}
                style={{
                  appearance: "none",
                  padding: "9px 36px 9px 34px",
                  fontSize: 13,
                  fontWeight: 500,
                  fontFamily: "'Josefin Sans', sans-serif",
                  color: C.maroon,
                  background: "rgba(255,249,240,.97)",
                  border: `1px solid rgba(196,152,10,.35)`,
                  borderRadius: 100,
                  cursor: "pointer",
                  outline: "none",
                  backdropFilter: "blur(8px)",
                  boxShadow: "0 2px 8px rgba(0,0,0,0.04)",
                }}
              >
                {STATUS_OPTIONS.map((s) => (
                  <option key={s} value={s}>
                    {s.charAt(0).toUpperCase() + s.slice(1)}
                  </option>
                ))}
              </select>
              <ChevronDown size={14} color={C.gold} style={{ position: "absolute", right: 14, top: "50%", transform: "translateY(-50%)", pointerEvents: "none" }} />
            </div>
          </div>

          {/* Stats Cards */}
          <div className="vb-stats-grid" style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(160px, 1fr))", gap: 16, marginBottom: 32 }}>
            {STAT_CARDS.map(({ key, filterKey, label, color, bg, border }) => (
              <div
                key={key}
                onClick={() => setFilter(filterKey as any)}
                style={{
                  background: "rgba(255,249,240,.97)",
                  backdropFilter: "blur(8px)",
                  border: `1px solid rgba(196,152,10,.22)`,
                  borderRadius: 20,
                  padding: "16px 20px",
                  cursor: "pointer",
                  transition: "transform 0.2s, box-shadow 0.2s",
                  boxShadow: "0 2px 8px rgba(0,0,0,0.04)",
