                  style={{
                    background: "rgba(255,249,240,.97)",
                    backdropFilter: "blur(10px)",
                    border: "1px solid rgba(196,152,10,.22)",
                    borderRadius: 24,
                    overflow: "hidden",
                    transition: "box-shadow 0.2s",
                    boxShadow: "0 4px 16px rgba(0,0,0,0.04)",
