type CollectionPayload = {
  name: string;
  slug: string;
  description: string;
  banner_image: string;
  is_active: boolean;
  featured: boolean;
  // ── NEW: category field sent to backend ────────────────────────────────────
  category: string;
};

type CollectionResponse = {
  data?: any;
  collection?: any;
};

const initialForm: CollectionPayload = {
  name: "",
  slug: "",
  description: "",
  banner_image: "",
  is_active: true,
  featured: false,
  category: "",      // ← new
};

export default function CollectionForm() {
  const { id } = useParams();
  const navigate = useNavigate();
  const isEdit = useMemo(() => !!id, [id]);

  const [form, setForm] = useState<CollectionPayload>(initialForm);
  const [loading, setLoading] = useState(false);
  const [pageLoading, setPageLoading] = useState(isEdit);
  const [uploadingImage, setUploadingImage] = useState(false);
  const imageInputRef = useRef<HTMLInputElement | null>(null);

  const updateField = <K extends keyof CollectionPayload>(
    key: K,
    value: CollectionPayload[K]
  ) => setForm((prev) => ({ ...prev, [key]: value }));

  // ── Fetch existing collection (edit mode) ──────────────────────────────────
  useEffect(() => {
    if (!isEdit || !id) return;

    const fetchCollection = async () => {
      try {
        const res = await adminApi.get<CollectionResponse>(`/collections/${id}`);
        const collection = res.data?.data || res.data?.collection || res.data;

        if (collection) {
          setForm({
            name: collection.name || "",
            slug: collection.slug || "",
            description: collection.description || "",
            banner_image:
              collection.banner_image ||
              collection.image ||
              collection.thumbnail ||
              "",
            is_active: collection.is_active ?? true,
            featured: collection.featured ?? false,
            category: collection.category || "",   // ← load saved category
          });
        }
      } catch (error) {
        console.error("Failed to fetch collection", error);
      } finally {
        setPageLoading(false);
      }
    };

    fetchCollection();
  }, [id, isEdit]);

  // ── Image upload ───────────────────────────────────────────────────────────
  const handleCollectionImageUpload = async (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      setUploadingImage(true);
      const imageUrl = await uploadCollectionImage(file);
      setForm((prev) => ({ ...prev, banner_image: imageUrl }));
    } catch (error) {
      console.error("Collection image upload failed", error);
      alert("Image upload failed");
    } finally {
      setUploadingImage(false);
      if (imageInputRef.current) imageInputRef.current.value = "";
    }
  };

  // ── Save ───────────────────────────────────────────────────────────────────
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const payload = { ...form };
      if (isEdit && id) {
        await adminApi.put(`/collections/${id}`, payload);
      } else {
        await adminApi.post("/collections", payload);
      }
      navigate("/admin/collections");
    } catch (error) {
      console.error("Failed to save collection", error);
      alert("Save failed");
    } finally {
      setLoading(false);
    }
  };

  if (pageLoading) {
    return (
      <AdminLayout title={isEdit ? "Edit Collection" : "New Collection"}>
        <div
          className="collection-form"
          style={{ textAlign: "center", padding: "60px 20px" }}
        >
          Loading collection data...
        </div>
      </AdminLayout>
    );
  }

  return (
    <>
      <style>{CSS}</style>
      <AdminLayout title={isEdit ? "Edit Collection" : "New Collection"}>
        <div className="collection-form">
          <form onSubmit={handleSubmit}>
            <div
              style={{
                display: "grid",
                gap: 28,
                gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))",
              }}
            >
              {/* ── Basic Details ── */}
              <div className="form-card">
                <div className="form-title">
                  <Layers
                    size={20}
                    style={{ display: "inline", marginRight: 8, color: C.gold }}
                  />
                  Basic Details
                </div>

                <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
                  {/* Name */}
                  <div>
                    <label className="form-label">Collection Name</label>
                    <input
                      className="form-input"
                      placeholder="e.g., Summer Silks"
                      value={form.name}
                      onChange={(e) => updateField("name", e.target.value)}
                      required
                    />
                  </div>

                  {/* Slug */}
                  <div>
                    <label className="form-label">Slug</label>
                    <input
                      className="form-input"
                      placeholder="e.g., summer-silks"
                      value={form.slug}
                      onChange={(e) => updateField("slug", e.target.value)}
                      required
                    />
                    <p className="form-hint">
                      URL-friendly identifier (lowercase, hyphens)
                    </p>
                  </div>

                  {/* ── NEW: Category dropdown ──────────────────────────────
                      This replaces the old name-guessing logic.
                      Whatever is selected here becomes the filter tag that
                      users see in CollectionsPage sidebar.
                  ─────────────────────────────────────────────────────────── */}
                  <div>
                    <label className="form-label">Category</label>
                    <select
                      className="form-select"
                      value={form.category}
                      onChange={(e) => updateField("category", e.target.value)}
                    >
                      <option value="">— Select a category —</option>
                      {COLLECTION_CATEGORIES.map((cat) => (
                        <option key={cat} value={cat}>
                          {cat}
                        </option>
                      ))}
                    </select>
                    <p className="form-hint">
                      This determines which filter tab the collection appears
                      under on the shop page.
                    </p>
                    {form.category && (
                      <div className="cat-preview">{form.category}</div>
                    )}
                  </div>

                  {/* Description */}
                  <div>
                    <label className="form-label">Description</label>
                    <textarea
                      className="form-textarea"
                      placeholder="Describe the collection..."
                      rows={5}
                      value={form.description}
                      onChange={(e) =>
                        updateField("description", e.target.value)
                      }
                    />
                  </div>

                  {/* Image upload */}
                  <div>
                    <label className="form-label">Collection Image</label>
                    <div className="upload-box">
                      <button
                        type="button"
                        className="upload-btn"
                        onClick={() => imageInputRef.current?.click()}
                      >
                        <Upload size={14} />
                        {uploadingImage ? "Uploading..." : "Upload Image"}
                      </button>

                      <input
                        ref={imageInputRef}
                        type="file"
                        accept="image/*"
                        onChange={handleCollectionImageUpload}
                        style={{ display: "none" }}
                      />

                      <p className="upload-hint">
                        Select image from your device. It will be uploaded
                        automatically.
                      </p>

                      {form.banner_image && (
                        <img
                          src={form.banner_image}
                          alt="Collection preview"
                          className="preview-img"
                        />
                      )}
                    </div>
                  </div>
                </div>
              </div>

              {/* ── Settings ── */}
              <div className="form-card">
                <div className="form-title">
                  <Sparkles
                    size={20}
                    style={{ display: "inline", marginRight: 8, color: C.gold }}
                  />
                  Settings
                </div>

                <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
                  <label className="form-checkbox-label">
                    <input
                      type="checkbox"
                      className="form-checkbox"
                      checked={form.featured}
                      onChange={(e) =>
                        updateField("featured", e.target.checked)
                      }
                    />
                    Featured Collection
                  </label>

                  <label className="form-checkbox-label">
                    <input
                      type="checkbox"
                      className="form-checkbox"
                      checked={form.is_active}
                      onChange={(e) =>
                        updateField("is_active", e.target.checked)
                      }
                    />
                    Active Collection
                  </label>

                  {form.banner_image && (
                    <div style={{ marginTop: 8 }}>
                      <p className="form-label">Preview</p>
                      <img
                        src={form.banner_image}
                        alt="Collection preview"
                        className="preview-img"
                        onError={(e) => {
                          (e.target as HTMLImageElement).style.display = "none";
                        }}
                      />
                    </div>
                  )}
                </div>
              </div>
            </div>

            {/* Action buttons */}
            <div
              style={{
                display: "flex",
                gap: 16,
                marginTop: 32,
                flexWrap: "wrap",
              }}
            >
              <button
                type="submit"
                disabled={loading}
                className="btn-save"
              >
                <Save size={16} />
                {loading
                  ? "Saving..."
                  : isEdit
                  ? "Update Collection"
                  : "Create Collection"}
              </button>
              <button
                type="button"
                onClick={() => navigate("/admin/collections")}
                className="btn-cancel"
              >
                <X size={16} />
                Cancel
              </button>
            </div>
          </form>
        </div>
      </AdminLayout>
    </>
  );
}

