type ProductPayload = {
  name: string;
  slug: string;
  price: number;
  discount_price: number | null;
  thumbnail: string;
  images: string[];
  short_description: string;
  // ── CHANGED: color & fabric are now arrays ────────────────────────────────
  color: string[];
  fabric: string[];
  // ─────────────────────────────────────────────────────────────────────────
  technique: string;
  stock: number;
  collection_id: string;
  collection_slug: string;
  is_featured: boolean;
  is_active: boolean;
};

type ProductResponse = {
  data?: any;
  product?: any;
};

type Collection = {
  id: string;
  name: string;
  slug: string;
};

const initialForm: ProductPayload = {
  name: "",
  slug: "",
  price: 0,
  discount_price: null,
  thumbnail: "",
  images: [],
  short_description: "",
  color: [],
  fabric: [],
  technique: "",
  stock: 0,
  collection_id: "",
  collection_slug: "",
  is_featured: false,
  is_active: true,
};

// Helper: parse "Red,Gold" string from API → ["Red","Gold"] array
const toArray = (v: string | string[] | null | undefined): string[] => {
  if (!v) return [];
  if (Array.isArray(v)) return v.filter(Boolean);
  return v.split(",").map((x) => x.trim()).filter(Boolean);
};

export default function ProductForm() {
  const { id } = useParams();
  const navigate = useNavigate();
  const isEdit = useMemo(() => !!id, [id]);

  const [form, setForm] = useState<ProductPayload>(initialForm);
  const [collections, setCollections] = useState<Collection[]>([]);
  const [loading, setLoading] = useState(false);
  const [pageLoading, setPageLoading] = useState(isEdit);
  const [collectionsLoading, setCollectionsLoading] = useState(true);
  const [uploadingImages, setUploadingImages] = useState(false);

  const imagesInputRef = useRef<HTMLInputElement | null>(null);

  const updateField = <K extends keyof ProductPayload>(
    key: K,
    value: ProductPayload[K]
  ) => setForm((prev) => ({ ...prev, [key]: value }));

  // ── Fetch collections ──────────────────────────────────────────────────────
  useEffect(() => {
    const fetchCollections = async () => {
      try {
        setCollectionsLoading(true);
        const res = await adminApi.get("/collections");
        let items: Collection[] = [];
        if (Array.isArray(res.data)) items = res.data;
        else if (Array.isArray(res.data?.data)) items = res.data.data;
        else if (Array.isArray(res.data?.data?.items)) items = res.data.data.items;
        else if (Array.isArray(res.data?.collections)) items = res.data.collections;
        else if (Array.isArray(res.data?.items)) items = res.data.items;
        setCollections(items);
      } catch (error) {
        console.error("Failed to fetch collections", error);
      } finally {
        setCollectionsLoading(false);
      }
    };
    fetchCollections();
  }, []);

  // ── Fetch product (edit mode) ──────────────────────────────────────────────
  useEffect(() => {
    if (!isEdit || !id) { setPageLoading(false); return; }

    const fetchProduct = async () => {
      try {
        const res = await adminApi.get<ProductResponse>(`/products/${id}`);
        const product = res.data?.data || res.data?.product || res.data;

        if (product) {
          setForm({
            name: product.name || "",
            slug: product.slug || "",
            price: Number(product.price || 0),
            discount_price:
              product.discount_price != null
                ? Number(product.discount_price)
                : null,
            thumbnail: product.thumbnail || "",
            images: Array.isArray(product.images) ? product.images : [],
            short_description: product.short_description || "",
            // ── Parse comma-string from DB back into array for the UI ─────────
            color: toArray(product.color),
            fabric: toArray(product.fabric),
            // ─────────────────────────────────────────────────────────────────
            technique: product.technique || "",
            stock: Math.max(0, Number(product.stock || 0)),
            collection_id:
              product.collection_id || product.collection?.id || "",
            collection_slug:
              product.collection_slug || product.collection?.slug || "",
            is_featured: !!product.is_featured,
            is_active: product.is_active ?? true,
          });
        }
      } catch (error) {
        console.error("Failed to fetch product", error);
      } finally {
        setPageLoading(false);
      }
    };

    fetchProduct();
  }, [id, isEdit]);

  const handleCollectionChange = (collectionId: string) => {
    const selected = collections.find((c) => c.id === collectionId);
    setForm((prev) => ({
      ...prev,
      collection_id: collectionId,
      collection_slug: selected?.slug || "",
    }));
  };

  // ── Image upload ───────────────────────────────────────────────────────────
  const handleImagesUpload = async (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    const files = Array.from(e.target.files || []);
    if (!files.length) return;
    try {
      setUploadingImages(true);
      const uploadedUrls: string[] = [];
      for (const file of files) {
        const url = await uploadProductImage(file);
        uploadedUrls.push(url);
      }
      setForm((prev) => ({
        ...prev,
        thumbnail: prev.thumbnail || uploadedUrls[0] || "",
        images: [...prev.images, ...uploadedUrls],
      }));
    } catch (error) {
      console.error("Images upload failed", error);
      alert("Images upload failed");
    } finally {
      setUploadingImages(false);
      if (imagesInputRef.current) imagesInputRef.current.value = "";
    }
  };

  const removeImage = (index: number) => {
    setForm((prev) => {
      const imageToRemove = prev.images[index];
      const updatedImages = prev.images.filter((_, i) => i !== index);
      return {
        ...prev,
        images: updatedImages,
        thumbnail:
          prev.thumbnail === imageToRemove
            ? updatedImages[0] || ""
            : prev.thumbnail,
      };
    });
  };

  // ── Submit ─────────────────────────────────────────────────────────────────
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const cleanedImages = form.images.filter((url) => url.trim() !== "");

      if (cleanedImages.length < 6) {
        alert("Please upload at least 6 product images.");
        setLoading(false);
        return;
      }

      const payload = {
        ...form,
        // ── Send arrays; backend _join() converts to "A,B,C" string ──────────
        color: form.color,      // string[]  →  backend → "Red,Gold"
        fabric: form.fabric,    // string[]  →  backend → "Silk,Cotton"
        // ─────────────────────────────────────────────────────────────────────
        discount_price:
          form.discount_price === null || form.discount_price === 0
            ? null
            : Math.max(0, Number(form.discount_price)),
        price: Math.max(0, Number(form.price)),
        stock: Math.max(0, Number(form.stock)),
        collection_id: form.collection_id || null,
        collection_slug: form.collection_slug || null,
        thumbnail: form.thumbnail || cleanedImages[0] || "",
        images: cleanedImages,
      };

      if (isEdit && id) {
        await adminApi.put(`/products/${id}`, payload);
      } else {
        await adminApi.post("/products", payload);
      }

      navigate("/admin/products");
    } catch (error: any) {
      console.error("Failed to save product", error);
      const validationErrors = error?.response?.data?.data;
      if (Array.isArray(validationErrors) && validationErrors.length > 0) {
        alert(validationErrors.map((err: any) => err.msg).join("\n"));
      } else {
        alert(
          error?.response?.data?.message ||
          error?.response?.data?.detail ||
          "Save failed"
        );
      }
    } finally {
      setLoading(false);
    }
  };

  if (pageLoading) {
    return (
      <AdminLayout title={isEdit ? "Edit Product" : "New Product"}>
        <div
          className="product-form"
          style={{ textAlign: "center", padding: "60px 20px" }}
        >
          Loading product data...
        </div>
      </AdminLayout>
    );
  }

  return (
    <>
      <style>{CSS}</style>
      <AdminLayout title={isEdit ? "Edit Product" : "New Product"}>
        <div className="product-form">
          <form onSubmit={handleSubmit}>
            <div
              style={{
                display: "grid",
                gap: 28,
                gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))",
              }}
            >
              {/* ── Basic Details ── */}
              <div className="form-card">
                <div className="form-title">
                  <Package size={20} color={C.gold} />
                  Basic Details
                </div>

                <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
                  <div>
                    <label className="form-label">Product Name</label>
                    <input
                      className="form-input"
                      placeholder="e.g., Banarasi Silk Saree"
                      value={form.name}
                      onChange={(e) => updateField("name", e.target.value)}
                      required
                    />
                  </div>

                  <div>
                    <label className="form-label">Slug</label>
                    <input
                      className="form-input"
                      placeholder="e.g., banarasi-silk-saree"
                      value={form.slug}
                      onChange={(e) => updateField("slug", e.target.value)}
                      required
                    />
                    <p className="slug-hint">
                      URL-friendly identifier (lowercase, hyphens)
                    </p>
                  </div>

                  <div>
                    <label className="form-label">Collection</label>
                    <select
                      className="form-select"
                      value={form.collection_id}
                      onChange={(e) => handleCollectionChange(e.target.value)}
                      disabled={collectionsLoading}
                    >
                      <option value="">
                        {collectionsLoading
                          ? "Loading collections..."
                          : "Select Collection"}
                      </option>
                      {collections.map((c) => (
                        <option key={c.id} value={c.id}>
                          {c.name}
                        </option>
                      ))}
                    </select>
                    {form.collection_slug && (
                      <p className="slug-hint" style={{ marginTop: 6 }}>
                        Collection slug: {form.collection_slug}
                      </p>
                    )}
                  </div>

                  <div>
                    <label className="form-label">Short Description</label>
                    <textarea
                      className="form-textarea"
                      placeholder="Brief description of the product..."
                      rows={4}
                      value={form.short_description}
                      onChange={(e) =>
                        updateField("short_description", e.target.value)
                      }
                    />
                  </div>

                  {/* Images */}
                  <div>
                    <label className="form-label">Product Images</label>
                    <div className="upload-box">
                      <div className="upload-actions">
                        <button
                          type="button"
                          className="upload-btn"
                          onClick={() => imagesInputRef.current?.click()}
                        >
                          <ImageIcon size={15} />
                          {uploadingImages
                            ? "Uploading..."
                            : "Upload Product Images"}
                        </button>
                      </div>
                      <input
                        ref={imagesInputRef}
                        type="file"
                        accept="image/*"
                        multiple
                        onChange={handleImagesUpload}
                        style={{ display: "none" }}
                      />
                      <p className="upload-hint">
                        Upload product images from your local folder. The first
                        image is automatically saved as the cover thumbnail.
                      </p>
                      <p className="upload-hint">
                        Uploaded images:{" "}
                        <strong>{form.images.length}</strong> / minimum{" "}
                        <strong>6</strong> required
                      </p>
                      {form.images.length > 0 && form.images.length < 6 && (
                        <p className="upload-warning">
                          Please upload at least 6 images for this product.
                        </p>
                      )}
                      {form.thumbnail ? (
                        <div className="cover-box">
                          <div className="cover-label">
                            <Star size={13} />
                            Cover Image
                          </div>
                          <img
                            src={form.thumbnail}
                            alt="Cover preview"
                            className="preview-img"
                          />
                        </div>
                      ) : null}
                      {form.images.length > 0 ? (
                        <div className="preview-grid">
                          {form.images.map((url, index) => (
                            <div key={index} className="preview-box">
                              <img
                                src={url}
                                alt={`Product ${index + 1}`}
                                className="preview-img-small"
                              />
                              {form.thumbnail === url && (
                                <div className="img-badge">
                                  <Star size={10} />
                                  Cover
                                </div>
                              )}
                              <button
                                type="button"
                                className="btn-remove-image"
                                onClick={() => removeImage(index)}
                              >
                                <Trash2 size={13} />
                              </button>
                            </div>
                          ))}
                        </div>
                      ) : null}
                    </div>
                  </div>
                </div>
              </div>

              {/* ── Pricing & Stock ── */}
              <div className="form-card">
                <div className="form-title">
                  <Sparkles size={20} color={C.gold} />
                  Pricing & Stock
                </div>

                <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
                  <div>
                    <label className="form-label">Price (₹)</label>
                    <input
                      type="number"
                      min={0}
                      className="form-input"
                      value={form.price}
                      onChange={(e) =>
                        updateField("price", Math.max(0, Number(e.target.value)))
                      }
                      required
                    />
                  </div>

                  <div>
                    <label className="form-label">Discount Amount (₹)</label>
                    <input
                      type="number"
                      min={0}
                      className="form-input"
                      placeholder="e.g. 200 (amount off the price)"
                      value={form.discount_price ?? ''}
                      onChange={(e) =>
                        updateField('discount_price', e.target.value ? Number(e.target.value) : null)
                      }
                    />
                    {form.discount_price != null && form.discount_price > 0 && form.price > 0 && (
                      <p className="form-hint" style={{ marginTop: 6 }}>
                        Selling price:{' '}
                        <strong style={{ color: '#800020' }}>
                          ₹{Math.max(0, form.price - form.discount_price).toLocaleString('en-IN')}
                        </strong>
                        {' '}·{' '}
                        <strong style={{ color: '#059669' }}>
                          {Math.round((form.discount_price / form.price) * 100)}% off
                        </strong>
                      </p>
                    )}
                  </div>

                  <div>
                    <label className="form-label">Stock Quantity</label>
                    <input
                      type="number"
                      min={0}
                      className="form-input"
                      value={form.stock}
                      onChange={(e) =>
                        updateField("stock", Math.max(0, Number(e.target.value)))
                      }
                    />
                  </div>

                  {/* ── NEW: Color tag input ───────────────────────────────── */}
                  <TagInput
                    label="Color"
                    values={form.color}
                    onChange={(v) => updateField("color", v)}
                    suggestions={COLOR_SUGGESTIONS}
                    placeholder="e.g. Red, Gold…"
                  />

                  {/* ── NEW: Fabric tag input ──────────────────────────────── */}
                  <TagInput
                    label="Fabric"
                    values={form.fabric}
                    onChange={(v) => updateField("fabric", v)}
                    suggestions={FABRIC_SUGGESTIONS}
                    placeholder="e.g. Silk, Cotton…"
                  />

                  <div>
                    <label className="form-label">Weaving Technique</label>
                    <input
                      className="form-input"
                      placeholder="e.g., Banarasi, Kanchipuram"
                      value={form.technique}
                      onChange={(e) =>
                        updateField("technique", e.target.value)
                      }
                    />
                  </div>
                </div>
              </div>
            </div>

            {/* ── Settings ── */}
            <div className="form-card" style={{ marginTop: 28 }}>
              <div className="form-title">
                <Layers size={20} color={C.gold} />
                Settings
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
                <label className="form-checkbox-label">
                  <input
                    type="checkbox"
                    className="form-checkbox"
                    checked={form.is_featured}
                    onChange={(e) =>
                      updateField("is_featured", e.target.checked)
                    }
                  />
                  Featured Product
                </label>
                <label className="form-checkbox-label">
                  <input
                    type="checkbox"
                    className="form-checkbox"
                    checked={form.is_active}
                    onChange={(e) =>
                      updateField("is_active", e.target.checked)
                    }
                  />
                  Active Product
                </label>
              </div>
            </div>

            <div style={{ display: "flex", gap: 16, marginTop: 32, flexWrap: "wrap" }}>
              <button
                type="submit"
                disabled={loading || uploadingImages}
                className="btn-save"
              >
                <Save size={16} />
                {loading
                  ? "Saving..."
                  : isEdit
                    ? "Update Product"
                    : "Create Product"}
              </button>
              <button
                type="button"
                onClick={() => navigate("/admin/products")}
                className="btn-cancel"
              >
                <X size={16} />
                Cancel
              </button>
            </div>
          </form>
        </div>
      </AdminLayout>
    </>
  );
}

