import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { X, Sparkles } from 'lucide-react';
import { getActiveFestivePopup } from '@/api/festiveCollections';
import { authService } from '@/lib/auth';

const CSS = `
