  border: 1px solid rgba(196,152,10,.3);
  padding: 5px 14px;
  border-radius: 100px;
  margin-bottom: 20px;
}
.popup-title {
  font-family: 'Cinzel', serif;
  font-size: 32px;
  font-weight: 500;
  color: #800020;
  line-height: 1.2;
  margin-bottom: 16px;
  letter-spacing: 0.02em;
