}
.popup-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 32px rgba(212,175,55,.52);
}
@media (max-width: 560px) {
  .popup-content { padding: 24px 20px 32px; }
  .popup-title { font-size: 28px; }
  .popup-img { height: 200px; }
}
`;

export function FestivePopup() {
  const [data, setData] = useState<any>(null);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const loadPopup = async () => {
      try {
        const user = authService.getCurrentUser();

        // show popup only when user is logged in
        if (!user) {
          setData(null);
          setOpen(false);
          return;
        }

        const festive = await getActiveFestivePopup();
        if (!festive) {
          setData(null);
          setOpen(false);
          return;
        }

        setData(festive);
        setOpen(true);
      } catch (error) {
        console.error('Failed to load festive popup:', error);
        setData(null);
        setOpen(false);
      }
    };

    loadPopup();
  }, []);

  const handleClose = () => {
    setOpen(false);
  };

  if (!open || !data) return null;

  return (
    <>
      <style>{CSS}</style>
      <div className="festive-popup-overlay" onClick={handleClose}>
        <div className="festive-popup-card" onClick={(e) => e.stopPropagation()}>
          <button type="button" className="popup-close" onClick={handleClose}>
            <X size={16} color="#9a8070" />
          </button>

          {data.banner_image ? (
            <img
              src={data.banner_image}
              alt={data.name}
              className="popup-img"
            />
          ) : null}

          <div className="popup-content">
            <div className="popup-ey">
              <Sparkles size={12} /> Festive Edit
            </div>

            <h2 className="popup-title">{data.name}</h2>

            <p className="popup-message">
              {data.popup_message ||
                data.description ||
                "Discover handcrafted festive sarees curated for your celebrations."}
            </p>

            <Link
              to={`/festive/${data.slug}`}
              onClick={handleClose}
              className="popup-btn"
            >
              Explore Collection
            </Link>
          </div>
        </div>
      </div>
    </>
  );
}

export default FestivePopup;

