`;

type CheckoutCreateResponse = {
  data?: {
    razorpay_order_id: string;
    amount: number;
    currency: string;
    key: string;
  };
};

type BackendCartResponse = {
  data?: {
    items?: Array<{
      product_id?: string;
      quantity?: number;
      product?: { id?: string };
    }>;
  };
};

export function CheckoutPage() {
  // ✅ Force scroll to top whenever this page is loaded/opened
  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  const navigate = useNavigate();
  const { cart, loading, getCartTotal, clearCart, refreshCart } = useCart();
  const user = authService.getCurrentUser();

  const [paymentMethod, setPaymentMethod] = useState('upi');
  const [isProcessing, setIsProcessing] = useState(false);

  useEffect(() => {
    if (!loading && cart.length === 0) {
      navigate('/cart');
    }
  }, [loading, cart.length, navigate]);

  useEffect(() => {
    if (!user) {
      navigate('/login');
    }
  }, [user, navigate]);

  if (loading) {
    return (
      <>
        <style>{CSS}</style>
        <div className="co-root">
          <div className="co-wrap co-page-top">
            <div style={{ textAlign: 'center', padding: '80px 0', color: C.maroon, fontFamily: "'Josefin Sans'" }}>
              Loading checkout...
            </div>
          </div>
        </div>
      </>
    );
  }

  if (cart.length === 0 || !user) {
    return null;
  }

  const subtotal = getCartTotal();
  const shipping = subtotal > 2999 ? 0 : 150;
  const total = subtotal + shipping;

  const loadRazorpayScript = async () => {
    return new Promise<boolean>((resolve) => {
      const existingScript = document.getElementById('razorpay-sdk');
      if (existingScript) {
        resolve(true);
        return;
      }

      const script = document.createElement('script');
      script.id = 'razorpay-sdk';
      script.src = 'https://checkout.razorpay.com/v1/checkout.js';
      script.async = true;
      script.onload = () => resolve(true);
      script.onerror = () => resolve(false);
      document.body.appendChild(script);
    });
  };

  const syncFrontendCartToBackend = async () => {
    // 1) read existing backend cart
    const backendCartRes = await api.get<BackendCartResponse>('/cart');
    const backendItems = backendCartRes.data?.data?.items || [];

    // 2) clear backend cart
    for (const item of backendItems) {
      const productId = item.product_id || item.product?.id;
      if (productId) {
        await api.post('/cart/remove', { product_id: productId });
      }
    }

    // 3) push current frontend cart to backend
    for (const item of cart) {
      await api.post('/cart/add', {
        product_id: item.saree.id,
        quantity: item.quantity,
      });
    }

    // 4) refresh shared cart state
    await refreshCart();
  };

  const handlePlaceOrder = async () => {
    if (!user) {
      toast.error('Please log in to continue');
      navigate('/login');
      return;
    }

    if (!user.addresses || user.addresses.length === 0) {
      toast.error('Please add a delivery address');
      return;
    }

    if (cart.length === 0) {
      toast.error('Cart is empty');
      return;
    }

    try {
      setIsProcessing(true);

      const sdkLoaded = await loadRazorpayScript();
      if (!sdkLoaded) {
        toast.error('Failed to load payment gateway');
        setIsProcessing(false);
        return;
      }

      const shippingAddress = {
        full_name: user.addresses[0].name,
        phone: user.addresses[0].phone,
        line1: user.addresses[0].addressLine1,
        line2: user.addresses[0].addressLine2 || '',
        city: user.addresses[0].city,
        state: user.addresses[0].state,
        postal_code: user.addresses[0].pincode,
        country: 'India',
      };

      // IMPORTANT: sync UI cart to backend cart before order creation
      await syncFrontendCartToBackend();

      const createRes = await api.post<CheckoutCreateResponse>('/orders/create', {
        shipping_address: shippingAddress,
        payment_method: paymentMethod,
      });

      const checkoutData = createRes.data?.data;

      if (!checkoutData?.razorpay_order_id || !checkoutData?.key) {
        throw new Error('Invalid checkout response');
      }

      const options = {
        key: checkoutData.key,
        amount: checkoutData.amount,
        currency: checkoutData.currency,
        name: 'Neyge Couture',
        description: 'Order Payment',
        order_id: checkoutData.razorpay_order_id,
        prefill: {
          name: user.name || '',
          email: user.email || '',
          contact: user.phone || shippingAddress.phone || '',
        },
        theme: {
          color: C.maroon,
        },
        handler: async function (response: any) {
          try {
            const verifyRes = await api.post('/payments/verify', {
              razorpay_order_id: response.razorpay_order_id,
              razorpay_payment_id: response.razorpay_payment_id,
              razorpay_signature: response.razorpay_signature,
            });

            console.log('VERIFY RESPONSE:', verifyRes.data);

            const createdOrder =
              verifyRes.data?.data ||
              verifyRes.data?.order ||
              verifyRes.data;

            await clearCart();

            toast.success('Order placed successfully!');

            setTimeout(() => {
              if (createdOrder?.id) {
                navigate(`/order-confirmation/${createdOrder.id}`, {
                  state: { order: createdOrder },
                });
              } else {
                navigate('/profile');
              }
            }, 300);
          } catch (error: any) {
            console.error('Payment verification failed', error);
            toast.error(
              error?.response?.data?.detail ||
              error?.response?.data?.message ||
              error?.message ||
              'Payment verification failed'
            );
          } finally {
            setIsProcessing(false);
          }
        },
        modal: {
          ondismiss: function () {
            setIsProcessing(false);
            toast.error('Payment cancelled');
          },
        },
      };

      const rzp = new window.Razorpay(options);
      rzp.open();
    } catch (error: any) {
      console.error('Order placement failed', error);
      toast.error(
        error?.response?.data?.detail ||
        error?.response?.data?.message ||
        error?.message ||
        'Failed to place order'
      );
      setIsProcessing(false);
    }
  };

  const PAY_OPTIONS = [
    {
      value: 'upi',
      Icon: Smartphone,
      title: 'UPI Payment',
      sub: 'Pay via UPI apps',
      bg: 'rgba(59,130,246,.12)',
      border: 'rgba(59,130,246,.35)',
      color: '#2563eb',
    },
    {
      value: 'card',
      Icon: CreditCard,
      title: 'Credit / Debit Card',
      sub: 'Visa, Mastercard, Rupay',
      bg: 'rgba(139,92,246,.12)',
      border: 'rgba(139,92,246,.35)',
      color: '#7c3aed',
    },
    {
      value: 'wallet',
      Icon: Wallet,
      title: 'Wallets',
      sub: 'Paytm, PhonePe, Amazon Pay',
      bg: 'rgba(16,185,129,.12)',
      border: 'rgba(16,185,129,.35)',
      color: '#059669',
    },
  ];

  return (
    <>
      <style>{CSS}</style>
      <div className="co-root">
        <div className="co-wrap co-page-top">
          <div className="co-header co-fadein">
            <div className="co-header-badge">
              <Shield size={13} color={C.gold} />
              <span className="ey">Secure Checkout</span>
            </div>
            <h1 className="co-header-title">Complete Your Order</h1>
            <div className="gd" style={{ marginTop: 16 }} />
          </div>

          <div className="co-layout">
            <div>
              <div className="co-card co-fadeup">
                <div className="co-card-head">
                  <div className="co-card-icon">
                    <MapPin size={18} color="white" />
                  </div>
                  <h2 className="co-card-title">Delivery Address</h2>
                </div>

                {user.addresses.length > 0 ? (
                  <div className="co-address-block">
                    <div style={{ display: 'flex', gap: 12, alignItems: 'flex-start' }}>
                      <div className="co-address-dot" />
                      <div>
                        <div className="co-address-name">{user.addresses[0].name}</div>
                        <div className="co-address-phone">{user.addresses[0].phone}</div>
                        <div className="co-address-line">
                          {user.addresses[0].addressLine1}
                          {user.addresses[0].addressLine2 && `, ${user.addresses[0].addressLine2}`}
                        </div>
                        <div className="co-address-line">
                          {user.addresses[0].city}, {user.addresses[0].state} – {user.addresses[0].pincode}
                        </div>
                      </div>
                    </div>
                  </div>
                ) : (
                  <div className="co-no-address">
                    <MapPin size={36} color={C.gold} style={{ margin: '0 auto' }} />
                    <p className="co-no-address-text">No address added. Please add a delivery address.</p>
                  </div>
                )}
              </div>

              <div className="co-card co-fadeup co-d1">
                <div className="co-card-head">
                  <div className="co-card-icon">
                    <Shield size={18} color="white" />
                  </div>
                  <h2 className="co-card-title">Payment Method</h2>
                </div>

                {PAY_OPTIONS.map(({ value, Icon, title, sub, bg, border, color }) => (
                  <label
                    key={value}
                    className={`co-pay-option${paymentMethod === value ? ' selected' : ''}`}
                    onClick={() => setPaymentMethod(value)}
                  >
                    <input
                      type="radio"
                      name="payment"
                      value={value}
                      checked={paymentMethod === value}
                      onChange={() => setPaymentMethod(value)}
                      style={{ position: 'absolute', opacity: 0, pointerEvents: 'none' }}
                    />
                    <div className="co-pay-icon" style={{ background: bg, border: `1px solid ${border}` }}>
                      <Icon size={18} color={color} />
                    </div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div className="co-pay-title">{title}</div>
                      <div className="co-pay-sub">{sub}</div>
                    </div>
                    <div className="co-pay-radio">
                      {paymentMethod === value && (
                        <svg width="10" height="10" viewBox="0 0 20 20" fill="white">
                          <path
                            fillRule="evenodd"
                            d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"
                            clipRule="evenodd"
                          />
                        </svg>
                      )}
                    </div>
                  </label>
                ))}
              </div>
            </div>

            <div className="co-summary co-fadein co-d2">
              <div className="co-summary-bar">
                <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 }}>
                  <Sparkles size={13} color="rgba(212,175,55,.75)" />
                  <span style={{ fontFamily: "'Josefin Sans'", fontSize: 10, letterSpacing: '.2em', textTransform: 'uppercase', color: 'rgba(255,255,255,.45)' }}>
                    Neyge Couture
                  </span>
                </div>
                <div className="co-summary-bar-title">Order Summary</div>
              </div>

              <div className="co-summary-body">
                <div className="co-item-list">
                  {cart.map((item) => (
                    <div key={item.saree.id} className="co-item-row">
                      <img
                        src={item.saree.image || item.saree.images?.[0] || ''}
                        alt={item.saree.name}
                        className="co-item-img"
                      />
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div className="co-item-name">{item.saree.name}</div>
                        <div className="co-item-qty">Qty: {item.quantity}</div>
                        <div className="co-item-price">{formatCurrency(item.saree.price * item.quantity)}</div>
                      </div>
                    </div>
                  ))}
                </div>

                <div className="co-sum-row">
                  <span className="co-sum-key">Subtotal</span>
                  <span className="co-sum-val">{formatCurrency(subtotal)}</span>
                </div>

                <div className="co-sum-row">
                  <span className="co-sum-key">Shipping</span>
                  {shipping === 0 ? (
                    <span className="co-sum-free">
                      <Sparkles size={12} /> FREE
                    </span>
                  ) : (
                    <span className="co-sum-val">{formatCurrency(shipping)}</span>
                  )}
                </div>

                <div className="co-total-strip">
                  <span className="co-total-label">Total Amount</span>
                  <span className="co-total-val">{formatCurrency(total)}</span>
                </div>

                <button className="co-place-btn" onClick={handlePlaceOrder} disabled={isProcessing}>
                  {isProcessing ? (
                    <>
                      <span className="co-spinner" />
                      Processing…
                    </>
                  ) : (
                    'Place Order ✦'
                  )}
                </button>

                <p className="co-place-note">
                  By placing this order, you agree to our Terms & Conditions
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}

import { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { ArrowRight } from 'lucide-react';
import { getFestiveCollectionBySlug } from '@/api/festiveCollections';
import { SareeCard } from '@/components/features/SareeCard';

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;500;600;700&family=Josefin+Sans:ital,wght@0,300;0,400;0,500;0,600;1,300;1,400&display=swap');

.festive-page-root {
  font-family: 'Josefin Sans', sans-serif;
  background: linear-gradient(170deg, #FFF9F0 0%, #F8EEE2 45%, #F5E6D3 100%);
  min-height: 100vh;
  color: #1a1010;
  line-height: 1;
}
.festive-wrap {
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 64px;
}
@media(max-width: 900px){ .festive-wrap { padding: 0 24px; } }
@media(max-width: 480px){ .festive-wrap { padding: 0 16px; } }

.ey {
  font-family: 'Josefin Sans', sans-serif;
  font-size: 10px;
  letter-spacing: 0.30em;
  text-transform: uppercase;
  color: #C4980A;
  font-weight: 600;
}
.gd { width: 44px; height: 1px; background: #C4980A; margin: 0 auto; }

@keyframes fadeUp { from{opacity:0;transform:translateY(22px)} to{opacity:1;transform:translateY(0)} }
@keyframes subtleKenBurns {
  0% { transform: scale(1); }
  100% { transform: scale(1.05); }
}
.fade-up { animation: fadeUp .8s cubic-bezier(.4,0,.2,1) both; }
.delay-1 { animation-delay: .12s; }
.delay-2 { animation-delay: .24s; }
.delay-3 { animation-delay: .36s; }

.hero-banner {
  position: relative;
  width: 100%;
  height: 480px;
  border-radius: 32px;
  overflow: hidden;
  margin-bottom: 56px;
  box-shadow: 0 20px 60px rgba(0,0,0,.12);
}
.hero-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  animation: subtleKenBurns 20s ease-in-out infinite alternate;
}
.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(90,0,22,.45) 0%, rgba(27,42,107,.65) 100%);
}
.hero-content {
  position: absolute;
  bottom: 40px;
  left: 0;
  right: 0;
  text-align: center;
  padding: 0 24px;
  color: white;
  z-index: 2;
}
.hero-title {
  font-family: 'Cinzel', serif;
  font-size: clamp(36px, 6vw, 64px);
  font-weight: 400;
  letter-spacing: 0.04em;
  margin-bottom: 12px;
  text-shadow: 0 2px 12px rgba(0,0,0,.3);
}
.hero-desc {
  font-family: 'Josefin Sans';
  font-size: 16px;
  font-weight: 300;
  max-width: 600px;
  margin: 0 auto;
  color: rgba(255,255,255,.85);
  text-shadow: 0 1px 6px rgba(0,0,0,.2);
}

.thread-divider {
  width: 100%;
  overflow: hidden;
  line-height: 0;
  padding: 8px 0;
  margin: 20px 0;
}
.thread-svg {
  width: 100%;
  height: 32px;
  display: block;
}
.thread-svg path {
  stroke: rgba(196,152,10,0.3);
  stroke-width: 1;
  fill: none;
  animation: flowThread 6s ease-in-out infinite;
}
@keyframes flowThread {
  0%,100% { d: path("M0,16 C300,4 600,28 900,16 C1200,4 1500,28 1800,16"); }
  50% { d: path("M0,12 C300,24 600,8 900,12 C1200,24 1500,8 1800,12"); }
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 28px;
  margin: 48px 0 64px;
}
@media(max-width: 1100px) { .product-grid { grid-template-columns: repeat(3, 1fr); } }
@media(max-width: 820px) { .product-grid { grid-template-columns: repeat(2, 1fr); gap: 20px; } }
@media(max-width: 560px) { .product-grid { grid-template-columns: 1fr; gap: 16px; } }

.back-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: 'Josefin Sans';
  font-size: 13px;
  font-weight: 500;
  color: #800020;
  text-decoration: none;
  margin-bottom: 32px;
  transition: gap .25s;
}
.back-link:hover { gap: 12px; color: #C4980A; }

.loading-state, .error-state {
  text-align: center;
  padding: 120px 24px;
  font-family: 'Josefin Sans';
  font-size: 14px;
  color: #4a3828;
}
`;

export default function FestiveCollectionPage() {
  // ✅ Force scroll to top whenever this page is loaded/opened
  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  const { slug = '' } = useParams();
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      try {
        setLoading(true);
        const res = await getFestiveCollectionBySlug(slug);
        setData(res);
      } catch (error) {
        console.error(error);
        setData(null);
      } finally {
        setLoading(false);
      }
    };
    if (slug) load();
  }, [slug]);

  if (loading) {
    return (
      <>
        <style>{CSS}</style>
        <div className="festive-page-root">
          <div className="loading-state">Loading festive collection...</div>
        </div>
      </>
    );
  }

  if (!data) {
    return (
      <>
        <style>{CSS}</style>
        <div className="festive-page-root">
          <div className="error-state">Festive collection not found</div>
        </div>
      </>
    );
  }

  const products = data.products || [];

  return (
    <>
      <style>{CSS}</style>
      <div className="festive-page-root">
        <div className="festive-wrap" style={{ paddingTop: 140, paddingBottom: 80 }}>
          {/* Back Link */}
          <Link to="/shop" className="back-link fade-up">
            ← Back to Shop
          </Link>

          {/* Hero Banner with Overlay */}
          <div className="hero-banner fade-up delay-1">
            {data.banner_image ? (
              <>
                <img src={data.banner_image} alt={data.name} className="hero-img" />
                <div className="hero-overlay" />
                <div className="hero-content">
                  <span className="ey" style={{ color: '#D4AF37', marginBottom: 8, display: 'block' }}>
                    Festive Collection
                  </span>
                  <h1 className="hero-title">{data.name}</h1>
                  {data.description && <p className="hero-desc">{data.description}</p>}
                </div>
              </>
            ) : (
              <div style={{ background: '#F5E6D3', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <h1 className="hero-title" style={{ color: '#800020' }}>{data.name}</h1>
              </div>
            )}
          </div>

          {/* Section Header */}
          <div style={{ textAlign: 'center', marginBottom: 32 }}>
            <span className="ey fade-up delay-2">Handpicked for You</span>
            <h2 className="fade-up delay-2" style={{ fontFamily: "'Cinzel', serif", fontSize: 'clamp(24px, 3.5vw, 36px)', fontWeight: 400, color: '#800020', marginTop: 12, letterSpacing: '0.04em' }}>
              Explore the Edit
            </h2>
            <div className="gd fade-up delay-2" style={{ margin: '16px auto 0' }} />
          </div>

          {/* Thread Divider */}
          <div className="thread-divider fade-up delay-3">
            <svg className="thread-svg" viewBox="0 0 1800 32" preserveAspectRatio="none">
              <path d="M0,16 C300,4 600,28 900,16 C1200,4 1500,28 1800,16" />
            </svg>
          </div>

          {/* Products Grid */}
          {products.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '60px 0' }}>
              <p style={{ fontFamily: "'Josefin Sans'", fontSize: 14, color: '#9a8070' }}>
                No products available in this festive collection yet.
              </p>
            </div>
          ) : (
            <div className="product-grid">
              {products.map((product: any, idx: number) => (
                <div
                  key={product.id}
                  style={{ animation: `fadeUp .6s ease ${idx * 0.06}s both` }}
                >
                  <SareeCard saree={product} />
                </div>
              ))}
            </div>
          )}

          {/* Optional CTA */}
          {products.length > 0 && (
            <div style={{ textAlign: 'center', marginTop: 32 }}>
              <Link
                to="/shop"
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: 10,
                  padding: '12px 32px',
                  background: 'linear-gradient(135deg, #D4AF37, #b8960f)',
                  color: '#800020',
                  borderRadius: 100,
                  fontFamily: "'Josefin Sans'",
                  fontSize: 12,
                  letterSpacing: '.12em',
                  fontWeight: 600,
                  textTransform: 'uppercase',
                  textDecoration: 'none',
                  transition: 'transform .35s, box-shadow .35s',
                  boxShadow: '0 4px 16px rgba(212,175,55,.3)',
                }}
              >
                View All Collections <ArrowRight size={14} />
              </Link>
            </div>
          )}
        </div>
      </div>
    </>
  );
}

